import React from 'react';

const SourcingOfferCard = ({ type, crop, quantity, location, contact }) => (
  <div className="bg-white dark:bg-[#2C2C2C] p-4 rounded shadow border dark:border-gray-700">
    <h3 className="text-lg font-bold text-gray-900 dark:text-white mb-1">{type}</h3>
    <p className="text-gray-700 dark:text-gray-300">Crop: {crop}</p>
    <p className="text-gray-700 dark:text-gray-300">Quantity: {quantity}</p>
    <p className="text-gray-700 dark:text-gray-300">Location: {location}</p>
    <p className="text-gray-700 dark:text-gray-300">Contact: {contact}</p>
  </div>
);

export default SourcingOfferCard;
